/**
 * SEO alias slugs for all 33 image conversion tools.
 *
 * 5 aliases per tool = 165 total alias URLs. Same pattern as
 * reel-downloader-aliases.ts and auto-caption-aliases.ts — each alias renders
 * the same underlying converter but with a unique H1, eyebrow, subline, and
 * metadata for a distinct search-intent keyword cluster. Each self-canonicalizes
 * so Google indexes it independently.
 */

export interface ConverterAlias {
  /** URL slug — the full path is /tools/<slug> */
  slug: string;
  /** Primary tool slug this alias belongs to (for tool resolution). */
  canonical: string;
  /** SEO title — ≤50 chars (template appends " | Trndinn"). */
  seoTitle: string;
  /** SEO meta description — 140-160 chars. */
  seoDescription: string;
  /** Keywords for meta + internal reporting. */
  keywords: string[];
  /** H1 text before the gradient-highlighted word. */
  h1Prefix: string;
  /** The gradient-highlighted word/phrase in the H1. */
  h1Highlight: string;
  /** H1 text after the gradient word. */
  h1Suffix: string;
  /** Small primary-tinted eyebrow badge above the hero. */
  eyebrow: string;
  /** Hero paragraph shown under the H1. */
  heroSubline: string;
}

