const ALIAS_MAP = new Map(ALIASES.map((a) => [a.slug, a]));

/** All alias slugs (165 total — 5 per tool × 33 tools). */
export const IMAGE_CONVERTER_ALIAS_SLUGS: string[] = ALIASES.map((a) => a.slug);

/** Map export for callers that need direct access. */
export const IMAGE_CONVERTER_ALIAS_MAP: Map<string, ConverterAlias> = ALIAS_MAP;

/** Fetch an alias definition by slug (returns undefined if not an alias). */
export function getConverterAlias(slug: string): ConverterAlias | undefined {
  return ALIAS_MAP.get(slug);
}

/** True if the given slug is an image converter alias. */
export function isConverterAliasSlug(slug: string): boolean {
  return ALIAS_MAP.has(slug);
}
